const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.gallery-item').forEach(item=>item.hidden=button.dataset.filter!=='all'&&item.dataset.category!==button.dataset.filter)}));
const lightbox=document.querySelector('#lightbox');document.querySelectorAll('.gallery-item').forEach(item=>item.addEventListener('click',()=>{const img=item.querySelector('img');lightbox.querySelector('img').src=img.src;lightbox.querySelector('img').alt=img.alt;lightbox.querySelector('p').textContent=img.alt+' · Registro do site da clínica';lightbox.showModal()}));document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const descriptions={'Estética facial':'Conheça nossa proposta de atenção à pele e converse sobre seus objetivos de autocuidado.','Estética corporal':'Reserve um momento para o corpo e descubra as opções de cuidado disponíveis.','Podologia':'Converse sobre os cuidados com seus pés e as suas necessidades para o dia a dia.'};const serviceDialog=document.querySelector('#service-dialog'),interest=document.querySelector('#interest'),message=document.querySelector('#message');function updateMessage(){message.value='Olá! Tenho interesse em '+interest.value.toLowerCase()+'. Gostaria de saber mais e consultar a disponibilidade.'}interest.addEventListener('change',updateMessage);document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#service-title').textContent=b.dataset.service;document.querySelector('#service-description').textContent=descriptions[b.dataset.service];serviceDialog.dataset.selected=b.dataset.service;serviceDialog.showModal()}));document.querySelector('#choose-service').addEventListener('click',()=>{interest.value=serviceDialog.dataset.selected;updateMessage();serviceDialog.close();document.querySelector('#contato').scrollIntoView({behavior:'smooth'})});document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();if(!message.value.trim()){document.querySelector('#form-status').textContent='Escreva sua mensagem para continuar.';return}window.open('https://wa.me/5548991520543?text='+encodeURIComponent(message.value),'_blank','noopener,noreferrer');});




// Movimento ativado por solicitação do proprietário: mouse e toque.
(()=>{const video=document.querySelector('#spa-scroll'),scene=document.querySelector('.scroll-scene');if(!video||!scene)return;const hero=video.parentElement;let target=0,frame=0;const clamp=n=>Math.max(0,Math.min(1,n));scene.classList.add('mouse-scene');scene.classList.remove('motion-off');scene.style.setProperty('--intro-opacity',1);scene.style.setProperty('--chapter-opacity',0);scene.style.setProperty('--intro-y','0px');const cue=scene.querySelector('.scroll-cue');if(cue)cue.textContent='Mova o mouse para baixo para explorar ↓';video.muted=true;video.preload='auto';function seek(){frame=0;if(!Number.isFinite(video.duration)||video.readyState<2||video.seeking)return;const t=target*Math.max(0,video.duration-.04);if(Math.abs(video.currentTime-t)>.025)video.currentTime=t;scene.style.setProperty('--scene-progress',target)}function request(){if(!frame)frame=requestAnimationFrame(seek)}function move(e){const r=hero.getBoundingClientRect();target=clamp((e.clientY-r.top)/r.height);request()}hero.addEventListener('pointermove',move,{passive:true});hero.addEventListener('mousemove',move,{passive:true});video.addEventListener('loadeddata',request);video.addEventListener('seeked',request);video.addEventListener('canplay',request);window.addEventListener('scroll',()=>{if(matchMedia('(pointer: coarse)').matches){const r=hero.getBoundingClientRect();target=clamp(-r.top/Math.max(1,r.height));request()}},{passive:true});video.load();})();

// Entrada única por seção; o conteúdo permanece acessível sem JavaScript.
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!reduced.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}})},{threshold:.08,rootMargin:'0px 0px -24px 0px'});document.querySelectorAll('.section-head,.cards article,.about-photo,.about-copy,.gallery-grid,.testimonials h2,.testimonials .quote,.faq>div,.contact>div,.contact form').forEach((el,i)=>{el.classList.add('reveal-ready');el.style.setProperty('--reveal-delay',el.closest('.cards')?((i%3)*80)+'ms':'0ms');observer.observe(el)});reduced.addEventListener('change',()=>{if(reduced.matches){document.querySelectorAll('.reveal-ready').forEach(el=>el.classList.add('is-visible'));observer.disconnect()}})}const bar=document.querySelector('.reading-progress');let pending=false;function update(){pending=false;const range=document.documentElement.scrollHeight-innerHeight;bar.style.transform='scaleX('+Math.max(0,Math.min(1,range>0?scrollY/range:0))+')';}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);update();if('IntersectionObserver' in window){const links=[...document.querySelectorAll('nav a[href^="#"]')];const sections=links.map(a=>document.querySelector(a.getAttribute('href'))).filter(Boolean);const active=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)links.forEach(a=>{if(a.getAttribute('href')==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})})},{rootMargin:'-15% 0px -55% 0px'});sections.forEach(s=>active.observe(s))}})();

// Fecha o menu móvel com Escape, ao sair dele e ao mudar para desktop.
(()=>{const trigger=document.querySelector('.menu'),navigation=document.querySelector('header nav');if(!trigger||!navigation)return;function close(){navigation.classList.remove('open');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','Abrir menu');}navigation.id='primary-navigation';trigger.setAttribute('aria-controls',navigation.id);navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){close();trigger.focus()}});document.addEventListener('click',e=>{if(!navigation.contains(e.target)&&!trigger.contains(e.target))close()});matchMedia('(min-width:701px)').addEventListener('change',e=>{if(e.matches)close()});})();



(()=>{const cards=[...document.querySelectorAll('.media-card')],filters=[...document.querySelectorAll('[data-media-filter]')],more=document.querySelector('.media-more'),count=document.querySelector('.media-count'),viewer=document.querySelector('#media-viewer'),stage=viewer.querySelector('.media-stage');let category='all',limit=6;function paint(){const matches=cards.filter(c=>category==='all'||c.dataset.category===category);cards.forEach(c=>c.hidden=true);matches.slice(0,limit).forEach(c=>c.hidden=false);more.hidden=matches.length<=limit;count.textContent=Math.min(limit,matches.length)+' de '+matches.length+' registros';}filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.mediaFilter;limit=6;filters.forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',String(f===b))});paint()}));more.addEventListener('click',()=>{limit+=6;paint()});cards.forEach(card=>card.addEventListener('click',()=>{stage.replaceChildren();const media=document.createElement(card.dataset.kind==='video'?'video':'img');media.src=card.dataset.src;if(card.dataset.kind==='video'){media.controls=true;media.playsInline=true;media.preload='metadata';media.poster=card.querySelector('img').src;}else media.alt=card.dataset.title;stage.append(media);document.querySelector('#media-viewer-title').textContent=card.dataset.title;viewer.querySelector('.media-viewer-footer a').href='https://wa.me/5548991520543?text='+encodeURIComponent('Olá! Gostaria de saber mais sobre '+card.dataset.title+'.');viewer.showModal();}));viewer.addEventListener('close',()=>{const v=stage.querySelector('video');if(v){v.pause();v.removeAttribute('src');v.load()}stage.replaceChildren()});paint()})();

(()=>{const banner=document.querySelector('#privacy-banner'),dialog=document.querySelector('#privacy-dialog'),key='ep-privacy-notice-v1';let remembered=false;try{const saved=JSON.parse(localStorage.getItem(key));remembered=!!saved&&Date.now()-saved.timestamp<180*86400000;if(!remembered)localStorage.removeItem(key)}catch{}banner.hidden=remembered;document.querySelector('#privacy-save').addEventListener('click',()=>{try{localStorage.setItem(key,JSON.stringify({timestamp:Date.now()}))}catch{}banner.hidden=true});document.querySelector('#privacy-dismiss').addEventListener('click',()=>banner.hidden=true);document.querySelectorAll('.privacy-open').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('#privacy-reset').addEventListener('click',()=>{try{localStorage.removeItem(key)}catch{}banner.hidden=false;document.querySelector('#privacy-status').textContent='Preferência apagada deste navegador.'})})();

